<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\Request;use App\Core\Response;use App\Services\ChargeCategoryService;
class ChargeCategoryController{private function send(array$r,int$ok=200):void{if(isset($r['error']))Response::json(['message'=>$r['error']],$r['status']??422);Response::json($r,$ok);}public function index():void{Response::json((new ChargeCategoryService())->all(!empty($_GET['active'])));}public function show():void{$r=(new ChargeCategoryService())->one((int)Request::param('id',0));if(!$r)Response::json(['message'=>'Catégorie introuvable'],404);Response::json($r);}public function store():void{$this->send((new ChargeCategoryService())->save(Request::json()),201);}public function update():void{$this->send((new ChargeCategoryService())->save(Request::json(),(int)Request::param('id',0)));}public function archive():void{$this->send((new ChargeCategoryService())->archive((int)Request::param('id',0)));}}
